mapper.select:
SELECT b.id as property_id, b.serial_number, b.`name`, b.file, b.type_name, b.`status`, b.price, b.purchase_date, a.department_id, a.create_by, a.creator_id, a.creator_type, a.handle_type_name, a.handle_time, a.remarks, b.imgs FROM property_history a INNER JOIN property_detailed b ON a.property_id = b.id
a.handle_time=#{param.handleTime}
a.handle_type_id=#{param.handleType}
and a.department_id=#{param.departmentId}
and b.status=#{param.status}
and b.type_id=#{param.typeId}
and (b.serial_number like concat('%',#{param.keywords},'%') or b.name like concat('%',#{param.keywords},'%'))
order by a.create_time desc, a.property_id
